const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  // Retried acknowledgement forwards the same receipt and never debits twice.
  {
    const ledger = new Ledger();
    const acked = [];
    let failures = 2;
    const service = new PaymentService(ledger, {
      acknowledge: async (receipt) => {
        if (failures-- > 0) throw new Transient('flake');
        acked.push(receipt);
      },
    });
    const receipt = await service.pay('shop', 'sale', 123, 3);
    assert.equal(ledger.entries.length, 1);
    assert.equal(acked.length, 1);
    assert.equal(acked[0], receipt);
    assert.deepEqual(receipt, { id: 1, tenant: 'shop', key: 'sale', cents: 123 });

    // A repeated equal amount returns the original receipt.
    const again = await service.pay('shop', 'sale', 123);
    assert.equal(again, receipt);
    assert.equal(ledger.entries.length, 1);
  }

  // Exhausted retries rethrow the final Transient as-is.
  {
    const ledger = new Ledger();
    const service = new PaymentService(ledger, {
      acknowledge: async () => { throw new Transient('down'); },
    });
    await assert.rejects(
      service.pay('t', 'k', 5, 2),
      (error) => error instanceof Transient && error.message === 'down',
    );
    assert.equal(ledger.entries.length, 1);
  }

  // attempts controls total acknowledgement tries.
  for (const [attempts, expectedTries] of [[1, 1], [5, 5]]) {
    const ledger = new Ledger();
    let tries = 0;
    const service = new PaymentService(ledger, {
      acknowledge: async () => { tries++; throw new Transient('down'); },
    });
    await assert.rejects(service.pay('t', 'k', 5, attempts), /down/);
    assert.equal(tries, expectedTries);
    assert.equal(ledger.entries.length, 1);
  }

  // Non-Transient errors are not retried.
  {
    const ledger = new Ledger();
    let tries = 0;
    const service = new PaymentService(ledger, {
      acknowledge: async () => { tries++; throw new Error('boom'); },
    });
    await assert.rejects(
      service.pay('t', 'k', 5),
      (error) => error instanceof Error && error.message === 'boom',
    );
    assert.equal(tries, 1);
    assert.equal(ledger.entries.length, 1);
  }

  // Same tenant/key with another amount throws 'key conflict' without a debit
  // and without an acknowledgement.
  {
    const ledger = new Ledger();
    let acks = 0;
    const service = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
    const receipt = await service.pay('t', 'k', 10);
    await assert.rejects(service.pay('t', 'k', 11), /key conflict/);
    assert.equal(ledger.entries.length, 1);
    assert.equal(acks, 1);
    assert.equal(await ledger.apply('t', 'k', 10), receipt);
    await assert.rejects(ledger.apply('t', 'k', 99), /key conflict/);
    assert.equal(ledger.entries.length, 1);
  }

  // Concurrent equal amounts share one debit and one receipt identity.
  {
    const ledger = new Ledger();
    const service = new PaymentService(ledger, { acknowledge: async () => {} });
    const [a, b] = await Promise.all([
      service.pay('t', 'k', 10),
      service.pay('t', 'k', 10),
    ]);
    assert.equal(a, b);
    assert.equal(ledger.entries.length, 1);
  }

  // Concurrent differing amounts: one wins, the other conflicts, one debit.
  {
    const ledger = new Ledger();
    const service = new PaymentService(ledger, { acknowledge: async () => {} });
    const settled = await Promise.allSettled([
      service.pay('t', 'k', 10),
      service.pay('t', 'k', 99),
    ]);
    const fulfilled = settled.filter((r) => r.status === 'fulfilled');
    const rejected = settled.filter((r) => r.status === 'rejected');
    assert.equal(fulfilled.length, 1);
    assert.equal(rejected.length, 1);
    assert.match(rejected[0].reason.message, /key conflict/);
    assert.equal(ledger.entries.length, 1);
  }

  // Different tenants are independent scopes.
  {
    const ledger = new Ledger();
    const service = new PaymentService(ledger, { acknowledge: async () => {} });
    const a = await service.pay('a', 'k', 1);
    const b = await service.pay('b', 'k', 1);
    assert.notEqual(a, b);
    assert.equal(ledger.entries.length, 2);
  }

  // Invalid input throws 'invalid payment' before any ledger or transport action.
  {
    const ledger = new Ledger();
    let acks = 0;
    const service = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
    for (const args of [
      ['', 'k', 10], ['t', '', 10], ['t', 'k', 0], ['t', 'k', -1],
      ['t', 'k', 1.5], ['t', 'k', NaN], ['t', 'k', 10, 0], ['t', 'k', 10, 6],
      ['t', 'k', 10, 2.5], ['t', 'k', 10, null],
    ]) {
      await assert.rejects(service.pay(...args), /invalid payment/);
    }
    assert.equal(ledger.entries.length, 0);
    assert.equal(acks, 0);
    // Sanity: a valid call still works right after the rejected ones.
    await service.pay('t', 'k', 10, 1);
    assert.equal(ledger.entries.length, 1);
    assert.equal(acks, 1);
  }

  console.log('idempotency checks passed');
}

module.exports = main();

