import { Ledger, Receipt } from './ledger';
import { Transient, Transport } from './transport';

const MIN_ATTEMPTS = 1;
const MAX_ATTEMPTS = 5;

export class PaymentService {
  constructor(private readonly ledger: Ledger, private readonly transport: Transport) {}
  async pay(tenant: string, key: string, cents: number, attempts = 3): Promise<Receipt> {
    // Validate everything before touching the ledger or the transport, so
    // invalid input can never produce a debit or an acknowledgement.
    if (
      !isNonEmptyString(tenant) ||
      !isNonEmptyString(key) ||
      !isPositiveInteger(cents) ||
      !Number.isInteger(attempts) ||
      attempts < MIN_ATTEMPTS ||
      attempts > MAX_ATTEMPTS
    ) {
      throw new Error('invalid payment');
    }

    // Debit exactly once. Any retry below re-acknowledges this same receipt,
    // so a retried payment can never duplicate the debit.
    const receipt = await this.ledger.apply(tenant, key, cents);

    let lastTransient: unknown;
    for (let tryIndex = 0; tryIndex < attempts; tryIndex++) {
      try {
        await this.transport.acknowledge(receipt);
        return receipt;
      } catch (error) {
        // Only Transient is retried, at most `attempts` total tries, always
        // forwarding the same receipt. The final exception is re-thrown as-is.
        if (!(error instanceof Transient)) throw error;
        lastTransient = error;
      }
    }
    throw lastTransient;
  }
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0;
}

function isPositiveInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value > 0;
}
